import numpy as np

def f(t):
    return t**3 - 3*t**2 - 9*t - 8

def count_nondiff(p, q):
    if f(-p) + q != 0:
        return None
    # F(x) = f(x-p)+q 의 계수
    xs = np.array([-3, -1, 0, 2, 4], dtype=float)
    coeffs = np.polyfit(xs, [f(t - p) + q for t in xs], 3)
    F = np.poly1d(np.round(coeffs, 6))
    def g(t):
        if abs(t) < 1e-12:
            return 0.0
        return np.sign(t)*abs(F(t))
    crit = []
    for r in list(np.roots(F.coeffs)) + [0.0]:
        if abs(np.imag(r)) < 1e-4 and all(abs(np.real(r) - c) > 1e-3 for c in crit):
            crit.append(float(np.real(r)))
    e = 1e-5
    n = 0
    for a in crit:
        sl = (g(a + e) - g(a))/e
        sr = (g(a) - g(a - e))/e
        if abs(sl - sr) > 1e-2:
            n += 1
    return n

def cand():
    out = set()
    for p in range(1, 60):
        q = -f(-p)
        if q >= 1 and count_nondiff(p, q) == 2:
            out.add(p + q)
    return out

def skill():
    return [p + (p**3 + 3*p**2 - 9*p + 8) for p in range(1, 60) if 3 < (p**3 + 3*p**2 - 9*p + 8) < 35][0]

def standard():
    v = cand()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(cand())
